{"command":"cat << 'EOF' > src/color.rs
use palette::{FromColor, Srgb, Hsl, Hsv, Lab, Lch, Oklab, Oklch};
use deltae::DE2000;
use crate::named::NAMED_COLORS;

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub alpha: f64,
}

impl Color {
    pub fn new(r: u8, g: u8, b: u8, alpha: f64) -> Self {
        Self { r, g, b, alpha }
    }

    pub fn from_rgb(r: u8, g: u8, b: u8) -> Self {
        Self { r, g, b, alpha: 1.0 }
    }

    pub fn from_hsl(h: f64, s: f64, l: f64, alpha: f64) -> Self {
        let palette_hsl = Hsl::new_srgb(h as f32, s as f32, l as f32);
        let rgb = Srgb::from_color(palette_hsl);
        let r = (rgb.red * 255.0).round().clamp(0.0, 255.0) as u8;
        let g = (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8;
        let b = (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8;
        Self { r, g, b, alpha }
    }

    pub fn to_hsl(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let hsl = Hsl::from_color(rgb);
        let (h, s, l) = hsl.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (hue, s as f64, l as f64)
    }

    pub fn to_hsv(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let hsv = Hsv::from_color(rgb);
        let (h, s, v) = hsv.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (hue, s as f64, v as f64)
    }

    pub fn to_lab(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let lab: Lab = Lab::from_color(rgb);
        (lab.l as f64, lab.a as f64, lab.b as f64)
    }

    pub fn to_lch(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let lch: Lch = Lch::from_color(rgb);
        let (l, c, h) = lch.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (l as f64, c as f64, hue)
    }

    pub fn to_oklab(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let oklab: Oklab = Oklab::from_color(rgb);
        (oklab.l as f64, oklab.a as f64, oklab.b as f64)
    }

    pub fn to_oklch(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let oklch: Oklch = Oklch::from_color(rgb);
        let (l, c, h) = oklch.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (l as f64, c as f64, hue)
    }

    pub fn luminance(&self) -> f64 {
        let f = |c: f64| {
            if c <= 0.04045 {
                c / 12.92
            } else {
                ((c + 0.055) / 1.055).powf(2.4)
            }
        };
        let r = f(self.r as f64 / 255.0);
        let g = f(self.g as f64 / 255.0);
        let b = f(self.b as f64 / 255.0);
        0.2126 * r + 0.7152 * g + 0.0722 * b
    }

    pub fn brightness(&self) -> f64 {
        (0.299 * (self.r as f64) + 0.587 * (self.g as f64) + 0.114 * (self.b as f64)) / 255.0
    }

    pub fn to_cmyk(&self) -> (f64, f64, f64, f64) {
        let r = self.r as f64 / 255.0;
        let g = self.g as f64 / 255.0;
        let b = self.b as f64 / 255.0;
        let k = 1.0 - r.max(g).max(b);
        if k >= 1.0 - 1e-9 {
            return (0.0, 0.0, 0.0, 100.0);
        }
        let c = (1.0 - r - k) / (1.0 - k);
        let m = (1.0 - g - k) / (1.0 - k);
        let y = (1.0 - b - k) / (1.0 - k);
        (c * 100.0, m * 100.0, y * 100.0, k * 100.0)
    }
}
EOF"}

