            return None;
        }

        match hex_str.len() {
            3 => {
                let r = u8::from_str_radix(&hex_str[0..1], 16).ok()? * 17;
                let g = u8::from_str_radix(&hex_str[1..2], 16).ok()? * 17;
                let b = u8::from_str_radix(&hex_str[2..3], 16).ok()? * 17;
                Some(Color::from_rgb(r, g, b))
            }
            4 => {
                let r = u8::from_str_radix(&hex_str[0..1], 16).ok()? * 17;
                let g = u8::from_str_radix(&hex_str[1..2], 16).ok()? * 17;
                let b = u8::from_str_radix(&hex_str[2..3], 16).ok()? * 17;
                let a = u8::from_str_radix(&hex_str[3..4], 16).ok()? * 17;
                Some(Color::new(r, g, b, a as f64 / 255.0))
            }
            6 => {
                let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
                let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
                let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
                Some(Color::from_rgb(r, g, b))
            }
            8 => {
                let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
                let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
                let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
                let a = u8::from_str_radix(&hex_str[6..8], 16).ok()?;
                Some(Color::new(r, g, b, a as f64 / 255.0))
            }
            _ => None,
        }
    }

    fn parse_func(s: &str) -> Option<Color> {
        let lower = s.to_lowercase();
        let open_paren = lower.find('(')?;
        let close_paren = lower.rfind(')')?;
        if close_paren <= open_paren {
            return None;
        }

        let name = lower[..open_paren].trim();
        let args_str = &lower[open_paren + 1..close_paren];
        let args: Vec<&str> = args_str.split(',').map(|a| a.trim()).collect();

        match name {
            "rgb" | "rgba" => {
                if args.len() < 3 || args.len() > 4 {
                    return None;
                }
                let r = parse_val_or_percent(args[0], 255.0)?;
                let g = parse_val_or_percent(args[1], 255.0)?;
                let b = parse_val_or_percent(args[2], 255.0)?;
                let alpha = if args.len() == 4 {
                    parse_alpha(args[3])?
                } else {
                    1.0
                };
                Some(Color::new(r.round().clamp(0.0, 255.0) as u8,
                                g.round().clamp(0.0, 255.0) as u8,
                                b.round().clamp(0.0, 255.0) as u8,
                                alpha.clamp(0.0, 1.0)))
            }
            "hsl" | "hsla" => {
                if args.len() < 3 || args.len() > 4 {
                    return None;
                }
                let h: f64 = args[0].trim_end_matches("deg").parse().ok()?;
                let s = parse_percent_or_float(args[1])?;
                let l = parse_percent_or_float(args[2])?;
                let alpha = if args.len() == 4 {
                    parse_alpha(args[3])?
                } else {
                    1.0
                };
                Some(Color::from_hsl(h, s.clamp(0.0, 1.0), l.clamp(0.0, 1.0), alpha.clamp(0.0, 1.0)))
            }
            "gray" => {
                if args.len() != 1 {
                    return None;
                }
                let l = parse_percent_or_float(args[0])?;
                Some(Color::from_hsl(0.0, 0.0, l.clamp(0.0, 1.0), 1.0))
            }
            _ => None,
        }
    }

    fn parse_comma(s: &str) -> Option<Color> {
        let args: Vec<&str> = s.split(',').map(|a| a.trim()).collect();
        if args.len() == 3 || args.len() == 4 {
            let r: f64 = args[0].parse().ok()?;
            let g: f64 = args[1].parse().ok()?;
            let b: f64 = args[2].parse().ok()?;
            let alpha = if args.len() == 4 {
                parse_alpha(args[3])?
            } else {
                1.0
            };
            Some(Color::new(r.round().clamp(0.0, 255.0) as u8,
                            g.round().clamp(0.0, 255.0) as u8,
                            b.round().clamp(0.0, 255.0) as u8,
                            alpha.clamp(0.0, 1.0)))
        } else {
            None
        }
    }

    pub fn to_ansi_8bit_index(&self) -> u8 {
        // Find closest color in 256-color palette (16..255) using CIEDE2000
        let (self_l, self_a, self_b) = self.to_lab();
        let self_lab = deltae::LabValue::new(self_l as f32, self_a as f32, self_b as f32).unwrap_or(deltae::LabValue::new(0.0, 0.0, 0.0).unwrap());

        let mut best_idx = 16u8;
        let mut best_dist = f32::MAX;

        for idx in 16u8..=255 {
            let (r, g, b) = ansi_8bit_to_rgb(idx);
            let c = Color::from_rgb(r, g, b);
            let (l, a, b_val) = c.to_lab();
            if let Ok(other_lab) = deltae::LabValue::new(l as f32, a as f32, b_val as f32) {
                let de = deltae::DeltaE::new(self_lab, other_lab, deltae::DE2000);
                let dist = *de.value();
                if dist < best_dist {
                    best_dist = dist;
                    best_idx = idx;
                }
            }
        }
        best_idx
    }

    pub fn distance_ciede2000(&self, other: &Color) -> f64 {
        let (l1, a1, b1) = self.to_lab();
        let (l2, a2, b2) = other.to_lab();
        let lab1 = deltae::LabValue::new(l1 as f32, a1 as f32, b1 as f32).unwrap_or(deltae::LabValue::new(0.0, 0.0, 0.0).unwrap());
        let lab2 = deltae::LabValue::new(l2 as f32, a2 as f32, b2 as f32).unwrap_or(deltae::LabValue::new(0.0, 0.0, 0.0).unwrap());
        let de = deltae::DeltaE::new(lab1, lab2, deltae::DE2000);
        *de.value() as f64
    }

    pub fn distance_cie76(&self, other: &Color) -> f64 {
        let (l1, a1, b1) = self.to_lab();
        let (l2, a2, b2) = other.to_lab();
        ((l1 - l2).powi(2) + (a1 - a2).powi(2) + (b1 - b2).powi(2)).sqrt()
    }

    pub fn closest_named_color(&self) -> &'static str {
        let mut best_name = "black";
        let mut best_dist = f64::MAX;

        for &(name, (r, g, b)) in NAMED_COLORS {
            let other = Color::from_rgb(r, g, b);
            let dist = self.distance_ciede2000(&other);
            if dist < best_dist {
                best_dist = dist;
                best_name = name;
            }
        }
        best_name
    }

    pub fn exact_name(&self) -> Option<&'static str> {
        for &(name, (r, g, b)) in NAMED_COLORS {
            if self.r == r && self.g == g && self.b == b && self.alpha >= 0.999 {
                return Some(name);
            }
        }
        None
    }
}

pub fn ansi_8bit_to_rgb(idx: u8) -> (u8, u8, u8) {
    if idx < 16 {
        // Standard ANSI
        match idx {
            0 => (0, 0, 0),
            1 => (128, 0, 0),
            2 => (0, 128, 0),
            3 => (128, 128, 0),
            4 => (0, 0, 128),
            5 => (128, 0, 128),
            6 => (0, 128, 128),
            7 => (192, 192, 192),
            8 => (128, 128, 128),
            9 => (255, 0, 0),
            10 => (0, 255, 0),
            11 => (255, 255, 0),
            12 => (0, 0, 255),
            13 => (255, 0, 255),
            14 => (0, 255, 255),
            15 => (255, 255, 255),
            _ => unreachable!(),
        }
    } else if idx <= 231 {
        // 6x6x6 color cube
        let i = idx - 16;
        let r_idx = i / 36;
        let g_idx = (i % 36) / 6;
        let b_idx = i % 6;
        let steps = [0, 95, 135, 175, 215, 255];
        (steps[r_idx as usize], steps[g_idx as usize], steps[b_idx as usize])
    } else {
        // Grayscale ramp
        let v = 8 + (idx - 232) * 10;
        (v, v, v)
    }
}

fn parse_val_or_percent(s: &str, max_val: f64) -> Option<f64> {
    if let Some(pct) = s.strip_suffix('%') {
        let v: f64 = pct.parse().ok()?;
        Some((v / 100.0) * max_val)
    } else {
        s.parse::<f64>().ok()
    }
}

fn parse_percent_or_float(s: &str) -> Option<f64> {
    if let Some(pct) = s.strip_suffix('%') {
        let v: f64 = pct.parse().ok()?;
        Some(v / 100.0)
    } else {
        let v: f64 = s.parse().ok()?;
        if v > 1.0 {
            Some(v / 100.0)
        } else {
            Some(v)
        }
    }
}

fn parse_alpha(s: &str) -> Option<f64> {
    if let Some(pct) = s.strip_suffix('%') {
        let v: f64 = pct.parse().ok()?;
        Some(v / 100.0)
    } else {
        let v: f64 = s.parse().ok()?;
        if v > 1.0 && v <= 255.0 {
            Some(v / 255.0)
        } else {
            Some(v)
        }
    }
}
