    };

    let rgb_str = if color.alpha < 0.999 {
        format!("rgba({}, {}, {}, {:.3})", color.r, color.g, color.b, color.alpha)
    } else {
        format!("rgb({}, {}, {})", color.r, color.g, color.b)
    };

    let hsl_str = if color.alpha < 0.999 {
        format!("hsla({:.0}, {:.1}%, {:.1}%, {:.3})", h.round(), s * 100.0, l * 100.0, color.alpha)
    } else {
