    let similar_colors: Vec<(&'static str, Color)> = if exact.is_some() {
        distances.into_iter().skip(1).take(2).map(|(name, (r, g, b), _)| (name, Color::from_rgb(r, g, b))).collect()
    } else {
        distances.into_iter().take(3).map(|(name, (r, g, b), _)| (name, Color::from_rgb(r, g, b))).collect()
