fn render_box_row(row: usize, color: &Color, mode: ResolvedColorMode) -> String {
    let check_light_24 = (240, 240, 240);
    let check_dark_24 = (181, 181, 181);
    let check_light_8 = 254;
    let check_dark_8 = 249;

    let get_check_cell = |fg_light: bool| -> String {
        match mode {
            ResolvedColorMode::Mode24Bit => {
                let (fg_r, fg_g, fg_b) = if fg_light { check_light_24 } else { check_dark_24 };
                let (bg_r, bg_g, bg_b) = if fg_light { check_dark_24 } else { check_light_24 };
                format!("\x1b[38;2;{};{};{};48;2;{};{};{}m▀\x1b[0m", fg_r, fg_g, fg_b, bg_r, bg_g, bg_b)
