                let fg = if fg_light { check_light_8 } else { check_dark_8 };
                let bg = if fg_light { check_dark_8 } else { check_light_8 };
                format!("\x1b[38;5;{};48;5;{}m▀\x1b[0m", fg, bg)
            }
            ResolvedColorMode::Off => " ".to_string(),
        }
    };

    if row == 0 || row == 7 {
        // Top or bottom border: 16 checkerboard cells
        let mut s = String::from("  ");
        for col in 0..16 {
            let fg_light = (row + col) % 2 == 0;
            s.push_str(&get_check_cell(fg_light));
        }
        s
    } else {
        // Middle rows: 2 left border cells, 12 inner cells, 2 right border cells
        let mut s = String::from("  ");
        s.push_str(&get_check_cell(row % 2 == 0));
        s.push_str(&get_check_cell(row % 2 != 0));

        // Inner 12 cells
        let inner = match mode {
            ResolvedColorMode::Mode24Bit => {
                format!("\x1b[38;2;{};{};{};48;2;{};{};{}m            \x1b[0m", color.r, color.g, color.b, color.r, color.g, color.b)
            }
            ResolvedColorMode::Mode8Bit => {
                let idx = color.to_ansi_8bit_index();
                format!("\x1b[38;5;{};48;5;{}m            \x1b[0m", idx, idx)
            }
            ResolvedColorMode::Off => "            ".to_string(),
        };
        s.push_str(&inner);

        s.push_str(&get_check_cell(row % 2 == 0));
        s.push_str(&get_check_cell(row % 2 != 0));
        s
    }
}

pub fn render_swatch(color: &Color, width: usize, mode: ResolvedColorMode) -> String {
    let spaces = " ".repeat(width);
    match mode {
        ResolvedColorMode::Mode24Bit => {
            format!("\x1b[38;2;{};{};{};48;2;{};{};{}m{}\x1b[0m", color.r, color.g, color.b, color.r, color.g, color.b, spaces)
        }
        ResolvedColorMode::Mode8Bit => {
            let idx = color.to_ansi_8bit_index();
            format!("\x1b[38;5;{};48;5;{}m{}\x1b[0m", idx, idx, spaces)
        }
        ResolvedColorMode::Off => spaces,
    }
}
