fn handle_to_gray(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let colors = get_colors(sub_matches, "color")?;
    let transformed: Vec<Color> = colors
        .iter()
        .map(|c| {
            let target_lum = c.luminance();
            // Find sRGB component g where sRGB_luminance(g) == target_lum
            let lin_g = if target_lum <= 0.0031308 {
                12.92 * target_lum
            } else {
                1.055 * target_lum.powf(1.0 / 2.4) - 0.055
            };
            let byte_v = (lin_g * 255.0).round().clamp(0.0, 255.0) as u8;
            Color::new(byte_v, byte_v, byte_v, c.alpha)
        })
        .collect();
    output_colors(&transformed, mode);
    Ok(())
}

