fn handle_complement(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let colors = get_colors(sub_matches, "color")?;
    let transformed: Vec<Color> = colors
        .iter()
        .map(|c| {
            let (h, s, l) = c.to_hsl();
            Color::from_hsl(h + 180.0, s, l, c.alpha)
        })
        .collect();
    output_colors(&transformed, mode);
    Ok(())
}

fn handle_darken(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let amount_str = sub_matches.get_one::<String>("amount").unwrap();
    let amount: f64 = amount_str.parse().map_err(|_| format!("Could not parse amount '{}'", amount_str))?;

    let colors = get_colors(sub_matches, "color")?;
    let transformed: Vec<Color> = colors
        .iter()
        .map(|c| {
            let (h, s, l) = c.to_hsl();
            Color::from_hsl(h, s, (l - amount).clamp(0.0, 1.0), c.alpha)
        })
        .collect();
    output_colors(&transformed, mode);
    Ok(())
}

fn handle_desaturate(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let amount_str = sub_matches.get_one::<String>("amount").unwrap();
    let amount: f64 = amount_str.parse().map_err(|_| format!("Could not parse amount '{}'", amount_str))?;

    let colors = get_colors(sub_matches, "color")?;
