fn handle_paint(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let color_str = sub_matches.get_one::<String>("color").unwrap();
    let fg_color = if color_str == "-" {
        let mut line = String::new();
        io::stdin().read_line(&mut line).map_err(|e| e.to_string())?;
        let trimmed = line.trim();
        Color::from_str(trimmed).ok_or_else(|| format!("Could not parse color '{}'", trimmed))?
    } else {
        Color::from_str(color_str).ok_or_else(|| format!("Could not parse color '{}'", color_str))?
    };

    let bg_color = if let Some(bg_str) = sub_matches.get_one::<String>("on") {
        Some(Color::from_str(bg_str).ok_or_else(|| format!("Could not parse color '{}'", bg_str))?)
    } else {
        None
    };

    let bold = sub_matches.get_flag("bold");
    let italic = sub_matches.get_flag("italic");
    let underline = sub_matches.get_flag("underline");
    let no_newline = sub_matches.get_flag("no-newline");

    let text_args: Vec<&str> = sub_matches
        .get_many::<String>("text")
        .map(|vals| vals.map(|s| s.as_str()).collect())
        .unwrap_or_default();

    let text = if !text_args.is_empty() {
        text_args.join(" ")
    } else {
        let mut input = String::new();
        let stdin = io::stdin();
        for line in stdin.lock().lines() {
            let l = line.map_err(|e| e.to_string())?;
            input.push_str(&l);
            input.push('\n');
        }
        if input.ends_with('\n') {
            input.pop();
        }
        input
    };

    if mode == ResolvedColorMode::Off {
        if no_newline {
            print!("{}", text);
        } else {
            println!("{}", text);
        }
        return Ok(());
    }

    let mut codes = Vec::new();
    match mode {
        ResolvedColorMode::Mode24Bit => {
            codes.push(format!("38;2;{};{};{}", fg_color.r, fg_color.g, fg_color.b));
            if let Some(bg) = bg_color {
                codes.push(format!("48;2;{};{};{}", bg.r, bg.g, bg.b));
            }
        }
        ResolvedColorMode::Mode8Bit => {
            codes.push(format!("38;5;{}", fg_color.to_ansi_8bit_index()));
            if let Some(bg) = bg_color {
                codes.push(format!("48;5;{}", bg.to_ansi_8bit_index()));
            }
        }
        ResolvedColorMode::Off => {}
    }

    if bold {
        codes.push("1".to_string());
    }
    if italic {
        codes.push("3".to_string());
    }
    if underline {
        codes.push("4".to_string());
    }

    let seq = codes.join(";");
    if no_newline {
        print!("\x1b[{}m{}\x1b[0m", seq, text);
    } else {
        println!("\x1b[{}m{}\x1b[0m", seq, text);
    }

    Ok(())
}

fn handle_pick(_sub_matches: &clap::ArgMatches, _mode: ResolvedColorMode) -> Result<(), String> {
    Err("Could not find any external color picker tool. See 'pastel pick --help' for more information.".into())
}
