fn get_colors(sub_matches: &clap::ArgMatches, arg_name: &str) -> Result<Vec<Color>, String> {
    let args: Option<Vec<&str>> = sub_matches
        .get_many::<String>(arg_name)
        .map(|vals| vals.map(|s| s.as_str()).collect());

    let mut colors = Vec::new();

    if let Some(arg_list) = args {
        if !arg_list.is_empty() {
            for arg in arg_list {
                if arg == "-" {
                    let mut line = String::new();
                    io::stdin().read_line(&mut line).map_err(|e| e.to_string())?;
                    let trimmed = line.trim();
                    if !trimmed.is_empty() {
                        let c = Color::from_str(trimmed)
                            .ok_or_else(|| format!("Could not parse color '{}'", trimmed))?;
                        colors.push(c);
                    }
                } else if arg == "pick" {
                    return Err("Could not find any external color picker tool. See 'pastel pick --help' for more information.".into());
                } else {
                    let c = Color::from_str(arg)
                        .ok_or_else(|| format!("Could not parse color '{}'", arg))?;
                    colors.push(c);
                }
            }
            return Ok(colors);
        }
    }

    let stdin = io::stdin();
    for line in stdin.lock().lines() {
        let line = line.map_err(|e| e.to_string())?;
        let trimmed = line.trim();
        if !trimmed.is_empty() {
            let c = Color::from_str(trimmed)
                .ok_or_else(|| format!("Could not parse color '{}'", trimmed))?;
            colors.push(c);
        }
    }

    Ok(colors)
}

fn output_colors(colors: &[Color], mode: ResolvedColorMode) {
    if std::io::stdout().is_terminal() && mode != ResolvedColorMode::Off {
        render_color_cards(colors, mode);
    } else {
        for c in colors {
            println!("{}", format_non_interactive(c));
        }
    }
}

fn handle_color(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let colors = get_colors(sub_matches, "color")?;
    output_colors(&colors, mode);
