        .iter()
        .map(|c| {
            let target_lum = c.luminance();
            // Find sRGB component g where sRGB_luminance(g) == target_lum
            let lin_g = if target_lum <= 0.0031308 {
                12.92 * target_lum
            } else {
                1.055 * target_lum.powf(1.0 / 2.4) - 0.055
