use std::env;
use std::io::{self, IsTerminal};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorMode {
    Mode24Bit,
    Mode8Bit,
    Off,
    Auto,
}

impl ColorMode {
    pub fn from_str(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "24bit" => Some(Self::Mode24Bit),
            "8bit" => Some(Self::Mode8Bit),
            "off" => Some(Self::Off),
            "auto" => Some(Self::Auto),
            _ => None,
        }
    }

    pub fn resolve(&self) -> ResolvedColorMode {
        match self {
            Self::Mode24Bit => ResolvedColorMode::Mode24Bit,
            Self::Mode8Bit => ResolvedColorMode::Mode8Bit,
            Self::Off => ResolvedColorMode::Off,
            Self::Auto => {
                if let Ok(val) = env::var("PASTEL_COLOR_MODE") {
                    if let Some(m) = Self::from_str(&val) {
                        if m != Self::Auto {
                            return m.resolve();
                        }
                    }
                }
                if !io::stdout().is_terminal() {
                    return ResolvedColorMode::Off;
                }
                if env::var("NO_COLOR").is_ok() {
                    return ResolvedColorMode::Off;
                }
                if let Ok(ct) = env::var("COLORTERM") {
                    if ct == "truecolor" || ct == "24bit" {
                        return ResolvedColorMode::Mode24Bit;
                    }
                }
                if let Ok(term) = env::var("TERM") {
                    if term.contains("24bit") || term.contains("truecolor") {
                        return ResolvedColorMode::Mode24Bit;
                    }
                }
                ResolvedColorMode::Mode8Bit
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResolvedColorMode {
    Mode24Bit,
    Mode8Bit,
    Off,
}

pub fn should_warn_about_24bit(color_mode: ColorMode) -> bool {
    if !io::stdout().is_terminal() {
        return false;
    }
    if color_mode == ColorMode::Mode24Bit || color_mode == ColorMode::Mode8Bit || color_mode == ColorMode::Off {
        return false;
    }
    if let Ok(val) = env::var("PASTEL_COLOR_MODE") {
        if val == "24bit" || val == "8bit" || val == "off" {
            return false;
        }
    }
    if let Ok(ct) = env::var("COLORTERM") {
        if ct == "truecolor" || ct == "24bit" {
            return false;
        }
    }
    true
}

pub fn print_24bit_warning() {
    eprintln!(
        "\x1b[38;5;226m[pastel warning]\x1b[0m: Your terminal emulator does not appear to support 24-bit colors (this means that the COLORTERM environment variable is not set to 'truecolor' or '24bit'). pastel will fall back to 8-bit colors, but you will only be able to see rough approximations of the real colors.\n\n\
To fix this, follow these steps:\n  \
1. Run 'pastel colorcheck' to test if your terminal\n     \
emulator does support 24-bit colors. If this is the\n     \
case, set 'PASTEL_COLOR_MODE=24bit' to force 24-bit\n     \
mode and to remove this warning. Alternatively, make\n     \
sure that COLORTERM is properly set by your terminal\n     \
emulator.\n  \
2. If your terminal emulator does not support 24-bit\n     \
colors, set 'PASTEL_COLOR_MODE=8bit' to remove this\n     \
warning or try a different terminal emulator.\n\n\
For more information, see https://gist.github.com/XVilka/8346728\n"
    );
}

pub fn print_error(msg: &str, resolved_mode: ResolvedColorMode) {
    match resolved_mode {
        ResolvedColorMode::Mode24Bit | ResolvedColorMode::Mode8Bit => {
            eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: {}", msg);
        }
        ResolvedColorMode::Off => {
            eprintln!("[pastel error]: {}", msg);
        }
    }
}
