{"command":"cat << 'EOF' > src/color.rs
use palette::{FromColor, Srgb, Hsl, Hsv, Lab, Lch, Oklab, Oklch};
use crate::named::NAMED_COLORS;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorblindType {
    Prot,
    Deuter,
    Trit,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub alpha: f64,
}

impl Color {
    pub fn new(r: u8, g: u8, b: u8, alpha: f64) -> Self {
        Self { r, g, b, alpha }
    }

    pub fn from_rgb(r: u8, g: u8, b: u8) -> Self {
        Self { r, g, b, alpha: 1.0 }
    }

    pub fn from_hsl(h: f64, s: f64, l: f64, alpha: f64) -> Self {
        let h_deg = (h % 360.0 + 360.0) % 360.0;
        let palette_hsl = Hsl::new_srgb(h_deg as f32, s as f32, l as f32);
        let rgb = Srgb::from_color(palette_hsl);
        let r = (rgb.red * 255.0).round().clamp(0.0, 255.0) as u8;
        let g = (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8;
        let b = (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8;
        Self { r, g, b, alpha }
    }

    pub fn to_hsl(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let hsl = Hsl::from_color(rgb);
        let (h, s, l) = hsl.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (hue, s as f64, l as f64)
    }

    pub fn to_hsv(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let hsv = Hsv::from_color(rgb);
        let (h, s, v) = hsv.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (hue, s as f64, v as f64)
    }

    pub fn to_lab(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let lab: Lab = Lab::from_color(rgb);
        (lab.l as f64, lab.a as f64, lab.b as f64)
    }

    pub fn to_lch(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let lch: Lch = Lch::from_color(rgb);
        let (l, c, h) = lch.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (l as f64, c as f64, hue)
    }

    pub fn to_oklab(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let oklab: Oklab = Oklab::from_color(rgb);
        (oklab.l as f64, oklab.a as f64, oklab.b as f64)
    }

    pub fn to_oklch(&self) -> (f64, f64, f64) {
        let rgb = Srgb::new(self.r as f32 / 255.0, self.g as f32 / 255.0, self.b as f32 / 255.0);
        let oklch: Oklch = Oklch::from_color(rgb);
        let (l, c, h) = oklch.into_components();
        let hue_deg = (h.into_degrees() as f64) % 360.0;
        let hue = if hue_deg < 0.0 { hue_deg + 360.0 } else { hue_deg };
        (l as f64, c as f64, hue)
    }

    pub fn luminance(&self) -> f64 {
        let f = |c: f64| {
            if c <= 0.04045 {
                c / 12.92
            } else {
                ((c + 0.055) / 1.055).powf(2.4)
            }
        };
        let r = f(self.r as f64 / 255.0);
        let g = f(self.g as f64 / 255.0);
        let b = f(self.b as f64 / 255.0);
        0.2126 * r + 0.7152 * g + 0.0722 * b
    }

    pub fn brightness(&self) -> f64 {
        (0.299 * (self.r as f64) + 0.587 * (self.g as f64) + 0.114 * (self.b as f64)) / 255.0
    }

    pub fn to_cmyk(&self) -> (f64, f64, f64, f64) {
        let r = self.r as f64 / 255.0;
        let g = self.g as f64 / 255.0;
        let b = self.b as f64 / 255.0;
        let k = 1.0 - r.max(g).max(b);
        if k >= 1.0 - 1e-9 {
            return (0.0, 0.0, 0.0, 100.0);
        }
        let c = (1.0 - r - k) / (1.0 - k);
        let m = (1.0 - g - k) / (1.0 - k);
        let y = (1.0 - b - k) / (1.0 - k);
        (c * 100.0, m * 100.0, y * 100.0, k * 100.0)
    }

    pub fn simulate_colorblind(&self, cb_type: ColorblindType) -> Color {
        let lin_r = srgb_to_linear(self.r as f64 / 255.0);
        let lin_g = srgb_to_linear(self.g as f64 / 255.0);
        let lin_b = srgb_to_linear(self.b as f64 / 255.0);

        let (r_mat, g_mat, b_mat) = match cb_type {
            ColorblindType::Prot => (
                [0.152286, 1.052583, -0.204868],
                [0.114503, 0.786281, 0.099216],
                [-0.003882, -0.048116, 1.051998],
            ),
            ColorblindType::Deuter => (
                [0.367322, 0.860646, -0.227968],
                [0.280085, 0.672501, 0.047413],
                [-0.011820, 0.042940, 0.968881],
            ),
            ColorblindType::Trit => (
                [1.255528, -0.076749, -0.178779],
                [-0.078411, 0.930809, 0.147602],
                [0.004733, 0.691367, 0.303900],
            ),
        };

        let lr = (r_mat[0] * lin_r + r_mat[1] * lin_g + r_mat[2] * lin_b).clamp(0.0, 1.0);
        let lg = (g_mat[0] * lin_r + g_mat[1] * lin_g + g_mat[2] * lin_b).clamp(0.0, 1.0);
        let lb = (b_mat[0] * lin_r + b_mat[1] * lin_g + b_mat[2] * lin_b).clamp(0.0, 1.0);

        let r = (linear_to_srgb(lr) * 255.0).round().clamp(0.0, 255.0) as u8;
        let g = (linear_to_srgb(lg) * 255.0).round().clamp(0.0, 255.0) as u8;
        let b = (linear_to_srgb(lb) * 255.0).round().clamp(0.0, 255.0) as u8;

        Color::new(r, g, b, self.alpha)
    }

    pub fn from_str(input: &str) -> Option<Color> {
        let s = input.trim();
        if s.is_empty() {
            return None;
        }

        // 1. Try named color
        let lower = s.to_lowercase();
        for &(name, (r, g, b)) in NAMED_COLORS {
            if name == lower {
                return Some(Color::from_rgb(r, g, b));
            }
        }

        // 2. Try hex
        if let Some(c) = Self::parse_hex(s) {
            return Some(c);
        }

        // 3. Try function notation rgb/rgba/hsl/hsla/gray
        if let Some(c) = Self::parse_func(s) {
            return Some(c);
        }

        // 4. Try comma-separated
        if let Some(c) = Self::parse_comma(s) {
            return Some(c);
        }

        None
    }

    fn parse_hex(s: &str) -> Option<Color> {
        let hex_str = s.strip_prefix('#').unwrap_or(s);
        if !hex_str.chars().all(|c| c.is_ascii_hexdigit()) {
            return None;
        }

        match hex_str.len() {
            3 => {
                let r = u8::from_str_radix(&hex_str[0..1], 16).ok()? * 17;
                let g = u8::from_str_radix(&hex_str[1..2], 16).ok()? * 17;
                let b = u8::from_str_radix(&hex_str[2..3], 16).ok()? * 17;
                Some(Color::from_rgb(r, g, b))
            }
            4 => {
                let r = u8::from_str_radix(&hex_str[0..1], 16).ok()? * 17;
                let g = u8::from_str_radix(&hex_str[1..2], 16).ok()? * 17;
                let b = u8::from_str_radix(&hex_str[2..3], 16).ok()? * 17;
                let a = u8::from_str_radix(&hex_str[3..4], 16).ok()? * 17;
                Some(Color::new(r, g, b, a as f64 / 255.0))
            }
            6 => {
                let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
                let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
                let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
                Some(Color::from_rgb(r, g, b))
            }
            8 => {
                let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
                let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
                let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
                let a = u8::from_str_radix(&hex_str[6..8], 16).ok()?;
                Some(Color::new(r, g, b, a as f64 / 255.0))
            }
            _ => None,
        }
    }

    fn parse_func(s: &str) -> Option<Color> {
        let lower = s.to_lowercase();
        let open_paren = lower.find('(')?;
        let close_paren = lower.rfind(')')?;
        if close_paren <= open_paren {
            return None;
        }

        let name = lower[..open_paren].trim();
        let args_str = &lower[open_paren + 1..close_paren];
        let args: Vec<&str> = args_str.split(',').map(|a| a.trim()).collect();

        match name {
            "rgb" | "rgba" => {
                if args.len() < 3 || args.len() > 4 {
                    return None;
                }
                let r = parse_val_or_percent(args[0], 255.0)?;
                let g = parse_val_or_percent(args[1], 255.0)?;
                let b = parse_val_or_percent(args[2], 255.0)?;
                let alpha = if args.len() == 4 {
                    parse_alpha(args[3])?
                } else {
                    1.0
                };
                Some(Color::new(r.round().clamp(0.0, 255.0) as u8,
                                g.round().clamp(0.0, 255.0) as u8,
                                b.round().clamp(0.0, 255.0) as u8,
                                alpha.clamp(0.0, 1.0)))
            }
            "hsl" | "hsla" => {
                if args.len() < 3 || args.len() > 4 {
                    return None;
                }
                let h: f64 = args[0].trim_end_matches("deg").parse().ok()?;
                let s = parse_percent_or_float(args[1])?;
                let l = parse_percent_or_float(args[2])?;
                let alpha = if args.len() == 4 {
                    parse_alpha(args[3])?
                } else {
                    1.0
                };
                Some(Color::from_hsl(h, s.clamp(0.0, 1.0), l.clamp(0.0, 1.0), alpha.clamp(0.0, 1.0)))
            }
            "gray" => {
                if args.len() != 1 {
                    return None;
                }
                let l = parse_percent_or_float(args[0])?;
                Some(Color::from_hsl(0.0, 0.0, l.clamp(0.0, 1.0), 1.0))
            }
            _ => None,
        }
    }

    fn parse_comma(s: &str) -> Option<Color> {
        let args: Vec<&str> = s.split(',').map(|a| a.trim()).collect();
        if args.len() == 3 || args.len() == 4 {
            let r: f64 = args[0].parse().ok()?;
            let g: f64 = args[1].parse().ok()?;
            let b: f64 = args[2].parse().ok()?;
            let alpha = if args.len() == 4 {
                parse_alpha(args[3])?
            } else {
                1.0
            };
            Some(Color::new(r.round().clamp(0.0, 255.0) as u8,
                            g.round().clamp(0.0, 255.0) as u8,
                            b.round().clamp(0.0, 255.0) as u8,
                            alpha.clamp(0.0, 1.0)))
        } else {
            None
        }
    }

    pub fn to_ansi_8bit_index(&self) -> u8 {
        let (self_l, self_a, self_b) = self.to_lab();
        let self_lab = deltae::LabValue::new(self_l as f32, self_a as f32, self_b as f32).unwrap_or(deltae::LabValue::new(0.0, 0.0, 0.0).unwrap());

        let mut best_idx = 16u8;
        let mut best_dist = f32::MAX;

        for idx in 16u8..=255 {
            let (r, g, b) = ansi_8bit_to_rgb(idx);
            let c = Color::from_rgb(r, g, b);
            let (l, a, b_val) = c.to_lab();
            if let Ok(other_lab) = deltae::LabValue::new(l as f32, a as f32, b_val as f32) {
                let de = deltae::DeltaE::new(self_lab, other_lab, deltae::DE2000);
                let dist = *de.value();
                if dist < best_dist {
                    best_dist = dist;
                    best_idx = idx;
                }
            }
        }
        best_idx
    }

    pub fn distance_ciede2000(&self, other: &Color) -> f64 {
        let (l1, a1, b1) = self.to_lab();
        let (l2, a2, b2) = other.to_lab();
        let lab1 = deltae::LabValue::new(l1 as f32, a1 as f32, b1 as f32).unwrap_or(deltae::LabValue::new(0.0, 0.0, 0.0).unwrap());
        let lab2 = deltae::LabValue::new(l2 as f32, a2 as f32, b2 as f32).unwrap_or(deltae::LabValue::new(0.0, 0.0, 0.0).unwrap());
        let de = deltae::DeltaE::new(lab1, lab2, deltae::DE2000);
        *de.value() as f64
    }

    pub fn distance_cie76(&self, other: &Color) -> f64 {
        let (l1, a1, b1) = self.to_lab();
        let (l2, a2, b2) = other.to_lab();
        ((l1 - l2).powi(2) + (a1 - a2).powi(2) + (b1 - b2).powi(2)).sqrt()
    }

    pub fn closest_named_color(&self) -> &'static str {
        let mut best_name = "black";
        let mut best_dist = f64::MAX;

        for &(name, (r, g, b)) in NAMED_COLORS {
            let other = Color::from_rgb(r, g, b);
            let dist = self.distance_ciede2000(&other);
            if dist < best_dist {
                best_dist = dist;
                best_name = name;
            }
        }
        best_name
    }

    pub fn exact_name(&self) -> Option<&'static str> {
        for &(name, (r, g, b)) in NAMED_COLORS {
            if self.r == r && self.g == g && self.b == b && self.alpha >= 0.999 {
                return Some(name);
            }
        }
        None
    }
}

pub fn ansi_8bit_to_rgb(idx: u8) -> (u8, u8, u8) {
    if idx < 16 {
        match idx {
            0 => (0, 0, 0),
            1 => (128, 0, 0),
            2 => (0, 128, 0),
            3 => (128, 128, 0),
            4 => (0, 0, 128),
            5 => (128, 0, 128),
            6 => (0, 128, 128),
            7 => (192, 192, 192),
            8 => (128, 128, 128),
            9 => (255, 0, 0),
            10 => (0, 255, 0),
            11 => (255, 255, 0),
            12 => (0, 0, 255),
            13 => (255, 0, 255),
            14 => (0, 255, 255),
            15 => (255, 255, 255),
            _ => unreachable!(),
        }
    } else if idx <= 231 {
        let i = idx - 16;
        let r_idx = i / 36;
        let g_idx = (i % 36) / 6;
        let b_idx = i % 6;
        let steps = [0, 95, 135, 175, 215, 255];
        (steps[r_idx as usize], steps[g_idx as usize], steps[b_idx as usize])
    } else {
        let v = 8 + (idx - 232) * 10;
        (v, v, v)
    }
}

fn srgb_to_linear(x: f64) -> f64 {
    if x <= 0.04045 {
        x / 12.92
    } else {
        ((x + 0.055) / 1.055).powf(2.4)
    }
}

fn linear_to_srgb(y: f64) -> f64 {
    if y <= 0.0031308 {
        12.92 * y
    } else {
        1.055 * y.powf(1.0 / 2.4) - 0.055
    }
}

fn parse_val_or_percent(s: &str, max_val: f64) -> Option<f64> {
    if let Some(pct) = s.strip_suffix('%') {
        let v: f64 = pct.parse().ok()?;
        Some((v / 100.0) * max_val)
    } else {
        s.parse::<f64>().ok()
    }
}

fn parse_percent_or_float(s: &str) -> Option<f64> {
    if let Some(pct) = s.strip_suffix('%') {
        let v: f64 = pct.parse().ok()?;
        Some(v / 100.0)
    } else {
        let v: f64 = s.parse().ok()?;
        if v > 1.0 {
            Some(v / 100.0)
        } else {
            Some(v)
        }
    }
}

fn parse_alpha(s: &str) -> Option<f64> {
    if let Some(pct) = s.strip_suffix('%') {
        let v: f64 = pct.parse().ok()?;
        Some(v / 100.0)
    } else {
        let v: f64 = s.parse().ok()?;
        if v > 1.0 && v <= 255.0 {
            Some(v / 255.0)
        } else {
            Some(v)
        }
    }
}
