fn format_color_to_type(c: &Color, fmt_type: &str) -> Result<String, String> {
    let (h, s, l) = c.to_hsl();
    let (h_v, s_v, v) = c.to_hsv();
    let (lab_l, lab_a, lab_b) = c.to_lab();
    let (lch_l, lch_c, lch_h) = c.to_lch();
    let (oklab_l, oklab_a, oklab_b) = c.to_oklab();
    let (oklch_l, oklch_c, oklch_h) = c.to_oklch();

    let res = match fmt_type {
        "rgb" => {
            if c.alpha < 0.999 {
                format!("rgba({}, {}, {}, {:.3})", c.r, c.g, c.b, c.alpha)
            } else {
                format!("rgb({}, {}, {})", c.r, c.g, c.b)
            }
        }
        "rgb-float" => {
            let rf = c.r as f64 / 255.0;
            let gf = c.g as f64 / 255.0;
            let bf = c.b as f64 / 255.0;
            if c.alpha < 0.999 {
                format!("rgba({:.3}, {:.3}, {:.3}, {:.3})", rf, gf, bf, c.alpha)
            } else {
                format!("rgb({:.3}, {:.3}, {:.3})", rf, gf, bf)
            }
        }
        "rgb-r" => format!("{}", c.r),
        "rgb-g" => format!("{}", c.g),
        "rgb-b" => format!("{}", c.b),
        "hex" => {
            if c.alpha < 0.999 {
                format!("#{:02x}{:02x}{:02x}{:02x}", c.r, c.g, c.b, (c.alpha * 255.0).round() as u8)
            } else {
                format!("#{:02x}{:02x}{:02x}", c.r, c.g, c.b)
            }
        }
        "hsl" => {
            if c.alpha < 0.999 {
                format!("hsla({:.0}, {:.1}%, {:.1}%, {:.3})", h.round(), s * 100.0, l * 100.0, c.alpha)
            } else {
                format!("hsl({:.0}, {:.1}%, {:.1}%)", h.round(), s * 100.0, l * 100.0)
            }
        }
        "hsl-hue" => format!("{:.0}", h.round()),
        "hsl-saturation" => format!("{:.4}", s),
        "hsl-lightness" => format!("{:.4}", l),
        "hsv" => {
            if c.alpha < 0.999 {
                format!("hsva({:.0}, {:.1}%, {:.1}%, {:.3})", h_v.round(), s_v * 100.0, v * 100.0, c.alpha)
            } else {
                format!("hsv({:.0}, {:.1}%, {:.1}%)", h_v.round(), s_v * 100.0, v * 100.0)
            }
        }
        "hsv-hue" => format!("{:.0}", h_v.round()),
        "hsv-saturation" => format!("{:.4}", s_v),
        "hsv-value" => format!("{:.4}", v),
        "lch" => {
            if c.alpha < 0.999 {
                format!("LCh({:.0}, {:.0}, {:.0}, {:.3})", lch_l.round(), lch_c.round(), lch_h.round(), c.alpha)
            } else {
                format!("LCh({:.0}, {:.0}, {:.0})", lch_l.round(), lch_c.round(), lch_h.round())
            }
        }
        "lch-lightness" => format!("{:.2}", lch_l),
        "lch-chroma" => format!("{:.2}", lch_c),
        "lch-hue" => format!("{:.2}", lch_h),
        "oklch" => {
            if c.alpha < 0.999 {
                format!("OkLCh({:.4}, {:.4}, {:.4}, {:.3})", oklch_l, oklch_c, oklch_h, c.alpha)
            } else {
                format!("OkLCh({:.4}, {:.4}, {:.4})", oklch_l, oklch_c, oklch_h)
            }
        }
        "oklch-lightness" => format!("{:.4}", oklch_l),
        "oklch-chroma" => format!("{:.4}", oklch_c),
        "oklch-hue" => format!("{:.4}", oklch_h),
        "lab" => {
            if c.alpha < 0.999 {
                format!("Lab({:.0}, {:.0}, {:.0}, {:.3})", lab_l.round(), lab_a.round(), lab_b.round(), c.alpha)
            } else {
                format!("Lab({:.0}, {:.0}, {:.0})", lab_l.round(), lab_a.round(), lab_b.round())
            }
        }
        "lab-a" => format!("{:.2}", lab_a),
        "lab-b" => format!("{:.2}", lab_b),
        "oklab" => {
            if c.alpha < 0.999 {
                format!("OkLab({:.4}, {:.4}, {:.4}, {:.3})", oklab_l, oklab_a, oklab_b, c.alpha)
            } else {
                format!("OkLab({:.4}, {:.4}, {:.4})", oklab_l, oklab_a, oklab_b)
            }
        }
        "oklab-l" => format!("{:.4}", oklab_l),
        "oklab-a" => format!("{:.4}", oklab_a),
        "oklab-b" => format!("{:.4}", oklab_b),
        "luminance" => format!("{:.3}", c.luminance()),
        "brightness" => format!("{:.3}", c.brightness()),
        "ansi-8bit" => format!("\\x1b[38;5;{}m", c.to_ansi_8bit_index()),
        "ansi-24bit" => format!("\\x1b[38;2;{};{};{}m", c.r, c.g, c.b),
        "ansi-8bit-value" => format!("{}", c.to_ansi_8bit_index()),
        "ansi-8bit-escapecode" => format!("\x1b[38;5;{}m", c.to_ansi_8bit_index()),
        "ansi-24bit-escapecode" => format!("\x1b[38;2;{};{};{}m", c.r, c.g, c.b),
        "cmyk" => {
            let (cyan, m, y, k) = c.to_cmyk();
            format!("cmyk({:.0}, {:.0}, {:.0}, {:.0})", cyan.round(), m.round(), y.round(), k.round())
        }
        "name" => c.closest_named_color().to_string(),
        _ => return Err(format!("Unknown format type '{}'", fmt_type)),
    };

    Ok(res)
}

fn handle_gradient(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let count_str = sub_matches.get_one::<String>("number").unwrap();
    let count: usize = count_str.parse().map_err(|_| format!("Could not parse count '{}'", count_str))?;

    let colorspace = sub_matches.get_one::<String>("colorspace").unwrap();
    let stops = get_colors(sub_matches, "color")?;

    if stops.is_empty() {
        return Err("Gradient requires at least one color stop".into());
    }
    if stops.len() == 1 || count <= 1 {
        output_colors(&stops, mode);
        return Ok(());
    }

    let mut result = Vec::new();
    let num_segments = stops.len() - 1;

    for i in 0..count {
        let t_global = i as f64 / (count - 1) as f64;
        let seg_f = t_global * num_segments as f64;
        let seg_idx = (seg_f.floor() as usize).min(num_segments - 1);
        let t = seg_f - seg_idx as f64;

        let interpolated = interpolate_colors(&stops[seg_idx], &stops[seg_idx + 1], t, colorspace);
        result.push(interpolated);
    }

    output_colors(&result, mode);
    Ok(())
}

fn handle_mix(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let base_str = sub_matches.get_one::<String>("base_color").unwrap();
    let base_color = Color::from_str(base_str).ok_or_else(|| format!("Could not parse color '{}'", base_str))?;

    let colorspace = sub_matches.get_one::<String>("colorspace").unwrap();
    let frac_str = sub_matches.get_one::<String>("fraction").unwrap();
    let fraction: f64 = frac_str.parse().map_err(|_| format!("Could not parse fraction '{}'", frac_str))?;

    let other_colors = get_colors(sub_matches, "color")?;

    let mut result = Vec::new();
    for other in &other_colors {
        let mixed = interpolate_colors(&base_color, other, 1.0 - fraction, colorspace);
        result.push(mixed);
    }

    output_colors(&result, mode);
    Ok(())
}

fn interpolate_colors(c1: &Color, c2: &Color, t: f64, colorspace: &str) -> Color {
    let alpha = (1.0 - t) * c1.alpha + t * c2.alpha;

    match colorspace {
        "RGB" => {
            let r = ((1.0 - t) * c1.r as f64 + t * c2.r as f64).round().clamp(0.0, 255.0) as u8;
            let g = ((1.0 - t) * c1.g as f64 + t * c2.g as f64).round().clamp(0.0, 255.0) as u8;
            let b = ((1.0 - t) * c1.b as f64 + t * c2.b as f64).round().clamp(0.0, 255.0) as u8;
            Color::new(r, g, b, alpha)
        }
        "HSL" => {
            let (h1, s1, l1) = c1.to_hsl();
            let (h2, s2, l2) = c2.to_hsl();
            let h = interp_angle(h1, h2, t);
            let s = (1.0 - t) * s1 + t * s2;
            let l = (1.0 - t) * l1 + t * l2;
            Color::from_hsl(h, s, l, alpha)
        }
        "Lab" => {
            let (l1, a1, b1) = c1.to_lab();
            let (l2, a2, b2) = c2.to_lab();
            let l = (1.0 - t) * l1 + t * l2;
            let a = (1.0 - t) * a1 + t * a2;
            let b = (1.0 - t) * b1 + t * b2;

            let lab = palette::Lab::new(l as f32, a as f32, b as f32);
            let rgb = palette::Srgb::from_color(lab);
            Color::new(
                (rgb.red * 255.0).round().clamp(0.0, 255.0) as u8,
                (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8,
                (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8,
                alpha,
            )
        }
        "LCh" => {
            let (l1, c1_val, h1) = c1.to_lch();
            let (l2, c2_val, h2) = c2.to_lch();
            let l = (1.0 - t) * l1 + t * l2;
            let chroma = (1.0 - t) * c1_val + t * c2_val;
            let h = interp_angle(h1, h2, t);

            let lch = palette::Lch::new(l as f32, chroma as f32, h as f32);
            let rgb = palette::Srgb::from_color(lch);
            Color::new(
                (rgb.red * 255.0).round().clamp(0.0, 255.0) as u8,
                (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8,
                (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8,
                alpha,
            )
        }
        "OkLab" => {
            let (l1, a1, b1) = c1.to_oklab();
            let (l2, a2, b2) = c2.to_oklab();
            let l = (1.0 - t) * l1 + t * l2;
            let a = (1.0 - t) * a1 + t * a2;
            let b = (1.0 - t) * b1 + t * b2;

            let oklab = palette::Oklab::new(l as f32, a as f32, b as f32);
            let rgb = palette::Srgb::from_color(oklab);
            Color::new(
                (rgb.red * 255.0).round().clamp(0.0, 255.0) as u8,
                (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8,
                (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8,
                alpha,
            )
        }
        _ => *c1,
    }
}

fn interp_angle(a1: f64, a2: f64, t: f64) -> f64 {
    let delta = (a2 - a1 + 540.0) % 360.0 - 180.0;
    (a1 + t * delta + 360.0) % 360.0
}

fn handle_random(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let count_str = sub_matches.get_one::<String>("number").unwrap();
    let count: usize = count_str.parse().map_err(|_| format!("Could not parse count '{}'", count_str))?;

    let strategy = sub_matches.get_one::<String>("strategy").unwrap();
    use rand::Rng;
    let mut rng = rand::thread_rng();

    let mut result = Vec::new();
    for _ in 0..count {
        let c = match strategy.as_str() {
            "vivid" => {
                let h = rng.gen_range(0.0..360.0);
                let s = rng.gen_range(0.4..0.8);
                let l = rng.gen_range(0.35..0.65);
                Color::from_hsl(h, s, l, 1.0)
            }
            "rgb" => {
                let r = rng.gen_range(0..=255);
                let g = rng.gen_range(0..=255);
                let b = rng.gen_range(0..=255);
                Color::from_rgb(r, g, b)
            }
            "gray" => {
                let l = rng.gen_range(0.0..1.0);
                Color::from_hsl(0.0, 0.0, l, 1.0)
            }
            "lch_hue" => {
                let h = rng.gen_range(0.0..360.0);
                let lch = palette::Lch::new(70.0f32, 35.0f32, h as f32);
                let rgb = palette::Srgb::from_color(lch);
                Color::from_rgb(
                    (rgb.red * 255.0).round().clamp(0.0, 255.0) as u8,
                    (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8,
                    (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8,
                )
            }
            _ => Color::from_rgb(0, 0, 0),
        };
        result.push(c);
    }

    output_colors(&result, mode);
    Ok(())
}

fn handle_list(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let sort_order = sub_matches.get_one::<String>("sort").unwrap();

    let mut colors: Vec<(&'static str, Color)> = NAMED_COLORS
        .iter()
        .map(|&(name, (r, g, b))| (name, Color::from_rgb(r, g, b)))
        .collect();

    sort_color_pairs(&mut colors, sort_order);

    let is_term = std::io::stdout().is_terminal() && mode != ResolvedColorMode::Off;

    for (name, c) in colors {
        if is_term {
            let textcolor = if c.luminance() > 0.1791 { (0, 0, 0) } else { (255, 255, 255) };
            match mode {
                ResolvedColorMode::Mode24Bit => {
                    println!("\x1b[38;2;{};{};{};48;2;{};{};{}m {:<24}\x1b[0m", textcolor.0, textcolor.1, textcolor.2, c.r, c.g, c.b, name);
                }
                ResolvedColorMode::Mode8Bit => {
                    let idx = c.to_ansi_8bit_index();
                    let fg_idx = if textcolor.0 == 0 { 16 } else { 231 };
                    println!("\x1b[38;5;{};48;5;{}m {:<24}\x1b[0m", fg_idx, idx, name);
                }
                ResolvedColorMode::Off => println!("{}", name),
            }
        } else {
            println!("{}", name);
        }
    }
    Ok(())
}

fn handle_sort_by(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let sort_order = sub_matches.get_one::<String>("sort-order").unwrap();
    let reverse = sub_matches.get_flag("reverse");
    let unique = sub_matches.get_flag("unique");

    let mut colors = get_colors(sub_matches, "color")?;

    if unique {
        let mut seen = Vec::new();
        colors.retain(|c| {
            if seen.contains(&(c.r, c.g, c.b)) {
                false
            } else {
                seen.push((c.r, c.g, c.b));
                true
            }
        });
    }

    let mut pairs: Vec<(&'static str, Color)> = colors.into_iter().map(|c| ("", c)).collect();
    sort_color_pairs(&mut pairs, sort_order);

    let mut sorted_colors: Vec<Color> = pairs.into_iter().map(|(_, c)| c).collect();
    if reverse {
        sorted_colors.reverse();
    }

    output_colors(&sorted_colors, mode);
    Ok(())
}

fn sort_color_pairs(colors: &mut [(&'static str, Color)], sort_order: &str) {
    match sort_order {
        "hue" => colors.sort_by(|a, b| a.1.to_hsl().0.partial_cmp(&b.1.to_hsl().0).unwrap_or(std::cmp::Ordering::Equal)),
        "brightness" => colors.sort_by(|a, b| a.1.brightness().partial_cmp(&b.1.brightness()).unwrap_or(std::cmp::Ordering::Equal)),
        "luminance" => colors.sort_by(|a, b| a.1.luminance().partial_cmp(&b.1.luminance()).unwrap_or(std::cmp::Ordering::Equal)),
        "chroma" => colors.sort_by(|a, b| a.1.to_lch().1.partial_cmp(&b.1.to_lch().1).unwrap_or(std::cmp::Ordering::Equal)),
        "random" => {
            use rand::seq::SliceRandom;
            let mut rng = rand::thread_rng();
            colors.shuffle(&mut rng);
        }
        _ => {}
    }
}

fn handle_set(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let prop = sub_matches.get_one::<String>("property").unwrap();
    let val_str = sub_matches.get_one::<String>("value").unwrap();
    let val: f64 = val_str.parse().map_err(|_| format!("Could not parse value '{}'", val_str))?;

    let colors = get_colors(sub_matches, "color")?;
    let mut result = Vec::new();

    for c in &colors {
        let new_c = match prop.as_str() {
            "lightness" => {
                let (_, chroma, h) = c.to_lch();
                let lch = palette::Lch::new(val as f32, chroma as f32, h as f32);
                let rgb = palette::Srgb::from_color(lch);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "hue" => {
                let (l, chroma, _) = c.to_lch();
                let lch = palette::Lch::new(l as f32, chroma as f32, val as f32);
                let rgb = palette::Srgb::from_color(lch);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "chroma" => {
                let (l, _, h) = c.to_lch();
                let lch = palette::Lch::new(l as f32, val as f32, h as f32);
                let rgb = palette::Srgb::from_color(lch);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "lab-a" => {
                let (l, _, b) = c.to_lab();
                let lab = palette::Lab::new(l as f32, val as f32, b as f32);
                let rgb = palette::Srgb::from_color(lab);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "lab-b" => {
                let (l, a, _) = c.to_lab();
                let lab = palette::Lab::new(l as f32, a as f32, val as f32);
                let rgb = palette::Srgb::from_color(lab);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "oklab-l" => {
                let (_, a, b) = c.to_oklab();
                let oklab = palette::Oklab::new(val as f32, a as f32, b as f32);
                let rgb = palette::Srgb::from_color(oklab);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "oklab-a" => {
                let (l, _, b) = c.to_oklab();
                let oklab = palette::Oklab::new(l as f32, val as f32, b as f32);
                let rgb = palette::Srgb::from_color(oklab);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "oklab-b" => {
                let (l, a, _) = c.to_oklab();
                let oklab = palette::Oklab::new(l as f32, a as f32, val as f32);
                let rgb = palette::Srgb::from_color(oklab);
                Color::new((rgb.red * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.green * 255.0).round().clamp(0.0, 255.0) as u8, (rgb.blue * 255.0).round().clamp(0.0, 255.0) as u8, c.alpha)
            }
            "red" => Color::new(val.round().clamp(0.0, 255.0) as u8, c.g, c.b, c.alpha),
            "green" => Color::new(c.r, val.round().clamp(0.0, 255.0) as u8, c.b, c.alpha),
            "blue" => Color::new(c.r, c.g, val.round().clamp(0.0, 255.0) as u8, c.alpha),
            "hsl-hue" => {
                let (_, s, l) = c.to_hsl();
                Color::from_hsl(val, s, l, c.alpha)
            }
            "hsl-saturation" => {
                let (h, _, l) = c.to_hsl();
                Color::from_hsl(h, val.clamp(0.0, 1.0), l, c.alpha)
            }
            "hsl-lightness" => {
                let (h, s, _) = c.to_hsl();
                Color::from_hsl(h, s, val.clamp(0.0, 1.0), c.alpha)
            }
            "alpha" => Color::new(c.r, c.g, c.b, val.clamp(0.0, 1.0)),
            _ => *c,
        };
        result.push(new_c);
    }

    output_colors(&result, mode);
    Ok(())
}

fn handle_paint(sub_matches: &clap::ArgMatches, mode: ResolvedColorMode) -> Result<(), String> {
    let color_str = sub_matches.get_one::<String>("color").unwrap();
    let fg_color = if color_str == "-" {
        let mut line = String::new();
        io::stdin().read_line(&mut line).map_err(|e| e.to_string())?;
        let trimmed = line.trim();
        Color::from_str(trimmed).ok_or_else(|| format!("Could not parse color '{}'", trimmed))?
    } else {
        Color::from_str(color_str).ok_or_else(|| format!("Could not parse color '{}'", color_str))?
    };

    let bg_color = if let Some(bg_str) = sub_matches.get_one::<String>("on") {
        Some(Color::from_str(bg_str).ok_or_else(|| format!("Could not parse color '{}'", bg_str))?)
    } else {
        None
    };

    let bold = sub_matches.get_flag("bold");
    let italic = sub_matches.get_flag("italic");
    let underline = sub_matches.get_flag("underline");
    let no_newline = sub_matches.get_flag("no-newline");

    let text_args: Vec<&str> = sub_matches
        .get_many::<String>("text")
        .map(|vals| vals.map(|s| s.as_str()).collect())
        .unwrap_or_default();

    let text = if !text_args.is_empty() {
        text_args.join(" ")
    } else {
        let mut input = String::new();
        let stdin = io::stdin();
        for line in stdin.lock().lines() {
            let l = line.map_err(|e| e.to_string())?;
            input.push_str(&l);
            input.push('\n');
        }
        if input.ends_with('\n') {
            input.pop();
        }
        input
    };

    if mode == ResolvedColorMode::Off {
        if no_newline {
            print!("{}", text);
        } else {
            println!("{}", text);
        }
        return Ok(());
    }

    let mut codes = Vec::new();
    match mode {
        ResolvedColorMode::Mode24Bit => {
            codes.push(format!("38;2;{};{};{}", fg_color.r, fg_color.g, fg_color.b));
            if let Some(bg) = bg_color {
                codes.push(format!("48;2;{};{};{}", bg.r, bg.g, bg.b));
            }
        }
        ResolvedColorMode::Mode8Bit => {
            codes.push(format!("38;5;{}", fg_color.to_ansi_8bit_index()));
            if let Some(bg) = bg_color {
                codes.push(format!("48;5;{}", bg.to_ansi_8bit_index()));
            }
        }
        ResolvedColorMode::Off => {}
    }

    if bold {
        codes.push("1".to_string());
    }
    if italic {
        codes.push("3".to_string());
    }
    if underline {
        codes.push("4".to_string());
    }

    let seq = codes.join(";");
    if no_newline {
        print!("\x1b[{}m{}\x1b[0m", seq, text);
    } else {
        println!("\x1b[{}m{}\x1b[0m", seq, text);
    }

    Ok(())
}

